<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">对比度检查</text><text class="nav-icon empty"> </text></view></view><view class="content"><view class="preview-box" :style="{ backgroundColor: bgColor, color: fgColor }"><text>测试文本 Sample Text</text></view><view class="color-row"><view class="color-col"><text class="c-label">前景色</text><input type="color" :value="fgColor" @input="fgColor=$event.detail.value" class="c-input"/></view><view class="color-col"><text class="c-label">背景色</text><input type="color" :value="bgColor" @input="bgColor=$event.detail.value" class="c-input"/></view></view><view class="result-box"><view class="r-row"><text>对比度: <text class="r-val">{{ contrast }}</text></text></view><view class="r-row"><text>WCAG AA: <text :class="passAA ? 'pass' : 'fail'">{{ passAA ? "通过" : "未通过" }}</text></text></view><view class="r-row"><text>WCAG AAA: <text :class="passAAA ? 'pass' : 'fail'">{{ passAAA ? "通过" : "未通过" }}</text></text></view></view></view></view></template><script setup>import { ref, computed, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const fgColor = ref("#000000"); const bgColor = ref("#ffffff")
function hexToRgb(hex) { var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16); return [r, g, b] }
function lum(hex) { var rgb = hexToRgb(hex).map(function(v) { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4) }); return 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2] }
const contrast = computed(function() { var l1 = lum(fgColor.value), l2 = lum(bgColor.value); var lighter = Math.max(l1, l2), darker = Math.min(l1, l2); return ((lighter + 0.05) / (darker + 0.05)).toFixed(2) })
const passAA = computed(function() { return parseFloat(contrast.value) >= 4.5 })
const passAAA = computed(function() { return parseFloat(contrast.value) >= 7 })
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#00b894,#00cec9);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.preview-box{height:200rpx;border-radius:20rpx;display:flex;align-items:center;justify-content:center;font-size:32rpx;margin-bottom:24rpx}.color-row{display:flex;gap:24rpx;margin-bottom:24rpx}.color-col{flex:1;background:#fff;border-radius:16rpx;padding:16rpx;text-align:center}.c-label{font-size:24rpx;color:#999;display:block;margin-bottom:8rpx}.c-input{width:100%;height:60rpx;border:none}.result-box{background:#fff;border-radius:20rpx;padding:24rpx}.r-row{padding:16rpx 0;border-bottom:2rpx solid #f0f0f0;font-size:28rpx;color:#333}.r-row:last-child{border-bottom:none}.r-val{font-weight:700;color:#00b894}.pass{color:#00b894;font-weight:700}.fail{color:#e17055;font-weight:700}</style>